//! End-to-end bridge round trip, exercised only through the crate's public
//! API (as an external caller would use it): an Air `SemanticDelta` goes in,
//! a signed agentbbs `ReplicateMessage` payload comes out over a simulated
//! in-memory transport, and the test verifies both the Ed25519 signature and
//! the rendered content. Loopback/simulation only — no live agentbbs peer,
//! per ADR-020's "What is simulated / what is hardware-pending" table.

use chrono::{DateTime, Utc};
use latentmesh_agentbbs_bridge::bridge::{self, delta_subject};
use latentmesh_agentbbs_bridge::transport::{FederationPublisher, InMemoryPeer};
use latentmesh_agentbbs_bridge::wire::{FederationPayload, Identity};
use latentmesh_air_core::{CriticalState, SymbolValue};

fn sample_delta() -> latentmesh_air_core::SemanticDelta {
    let mut before = CriticalState::new();
    before.set(10, SymbolValue::U64(1)).unwrap();
    let mut after = before.clone();
    after.set(10, SymbolValue::U64(2)).unwrap();
    after.set(11, SymbolValue::Bool(true)).unwrap();
    latentmesh_air_core::SemanticDelta::between(42, 1, 7, &before, &after, Vec::new()).unwrap()
}

#[test]
fn air_delta_in_bbs_message_out_over_simulated_transport() {
    let identity = Identity::generate();
    let delta = sample_delta();
    let created_at: DateTime<Utc> = "2026-08-27T09:30:00Z".parse().unwrap();

    // Publish path: SemanticDelta -> signed ReplicateMessage -> sealed
    // FederationEnvelope -> wire bytes handed to the sink.
    let payload =
        bridge::delta_to_replicate_payload(&identity, "air-relay", &delta, "gateway-1", created_at)
            .unwrap();

    let mut publisher = FederationPublisher::new(&identity, InMemoryPeer::new());
    let sealed = publisher.publish(payload).unwrap();
    assert_eq!(sealed.node, identity.id());
    assert_eq!(sealed.seq, 1);

    // Receive path: parse the wire bytes back, verify the envelope
    // signature, and confirm the message content and its own signature.
    let sink = publisher.into_sink();
    assert_eq!(sink.received.len(), 1);
    let opened = sink.opened_payloads().unwrap();
    assert_eq!(opened.len(), 1);

    match &opened[0] {
        FederationPayload::ReplicateMessage(message) => {
            assert!(message.verify().is_ok());
            assert_eq!(message.body.board, "air-relay");
            assert_eq!(message.body.subject, delta_subject(&delta));
            assert_eq!(message.body.author, identity.id());
            assert!(message.body.body.contains("source_id=42"));
            assert!(message.body.body.contains("set field=10 value=u64:2"));
            assert!(message.body.body.contains("set field=11 value=bool:true"));
        }
        other => panic!("expected ReplicateMessage, got {other:?}"),
    }
}

#[test]
fn post_message_args_path_matches_replicate_message_content() {
    // The two publish paths ADR-020 names (post_message MCP call vs.
    // ReplicateMessage federation payload) must render identical bulletin
    // content for the same delta, since they are two transports for the
    // same decoded fact.
    let delta = sample_delta();
    let args = bridge::delta_to_post_args("air-relay", &delta);

    let identity = Identity::generate();
    let created_at: DateTime<Utc> = "2026-08-27T09:30:00Z".parse().unwrap();
    let message =
        bridge::sign_delta_message(&identity, "air-relay", &delta, "gw", created_at).unwrap();

    assert_eq!(args["board"], "air-relay");
    assert_eq!(args["subject"], message.body.subject);
    assert_eq!(args["text"], message.body.body);
}

#[test]
fn discovery_path_announce_and_hello() {
    let identity = Identity::generate();
    let created_at: DateTime<Utc> = "2026-08-27T09:30:00Z".parse().unwrap();
    let state_hash = [0xAB_u8; 16];
    let board = bridge::air_stream_board(
        "air-relay",
        "LatentMesh Air Relay",
        identity.id(),
        &state_hash,
        created_at,
    );
    assert!(board.federated);
    assert!(board.description.contains(&hex::encode(state_hash)));

    let mut publisher = FederationPublisher::new(&identity, InMemoryPeer::new());
    publisher.publish(bridge::announce_board(board)).unwrap();
    publisher
        .publish(bridge::peer_hello(identity.id()))
        .unwrap();

    let sink = publisher.into_sink();
    let opened = sink.opened_payloads().unwrap();
    assert!(matches!(opened[0], FederationPayload::AnnounceBoard(_)));
    assert!(matches!(opened[1], FederationPayload::PeerHello { .. }));
}

//! Byte-stable golden JSON samples for each of the four `FederationPayload`
//! variants this crate implements, asserted against the field order and tag
//! scheme transcribed from `agentbbs-federation/src/envelope.rs`.
//!
//! Hermetic: no I/O, no network, no subprocess. AgentId/signature hex and
//! chrono's own RFC3339 rendering are captured from the values under test
//! (not hand-guessed), so what's actually being pinned here is agentbbs's
//! wire *shape* — the `"type"` tag values, `snake_case` naming, and struct
//! field order — which is exactly the part of the contract that could
//! silently regress.

use chrono::{DateTime, Utc};
use latentmesh_agentbbs_bridge::wire::{
    AgentId, Board, FederationPayload, Identity, Message, MessageBody, MessageKind,
};

fn fixed_created_at() -> DateTime<Utc> {
    "2026-08-27T12:00:00Z".parse().unwrap()
}

/// The exact JSON fragment chrono produces for `created_at`, captured from
/// the same value under test rather than assumed.
fn json_of<T: serde::Serialize>(value: &T) -> String {
    serde_json::to_string(value).unwrap()
}

#[test]
fn announce_board_golden_shape() {
    let founder = Identity::from_seed(&[7u8; 32]).id();
    let created_at = fixed_created_at();
    let board = Board {
        slug: "air-relay".into(),
        title: "LatentMesh Air Relay".into(),
        description: "Store-and-forward bulletin for an Air stream".into(),
        locked: false,
        founder,
        created_at,
        federated: true,
    };
    let payload = FederationPayload::AnnounceBoard(board);
    let actual = json_of(&payload);

    let expected = format!(
        concat!(
            r#"{{"type":"announce_board","slug":"air-relay","title":"LatentMesh Air Relay","#,
            r#""description":"Store-and-forward bulletin for an Air stream","locked":false,"#,
            r#""founder":"{founder_hex}","created_at":{created_json},"federated":true}}"#
        ),
        founder_hex = founder.to_hex(),
        created_json = json_of(&created_at),
    );
    assert_eq!(actual, expected);
}

#[test]
fn replicate_message_golden_shape() {
    let identity = Identity::from_seed(&[9u8; 32]);
    let created_at = fixed_created_at();
    let body = MessageBody {
        board: "air-relay".into(),
        parent: None,
        subject: "air-delta source=7 epoch=3 msg=99".into(),
        body: "LatentMesh Air state delta\n".into(),
        author: identity.id(),
        handle: "gateway-1".into(),
        created_at,
        kind: MessageKind::Post,
    };
    let message = Message::sign(&identity, body).unwrap();
    let payload = FederationPayload::ReplicateMessage(message.clone());
    let actual = json_of(&payload);

    let expected = format!(
        concat!(
            r#"{{"type":"replicate_message","id":{id_json},"body":{{"board":"air-relay","#,
            r#""parent":null,"subject":"air-delta source=7 epoch=3 msg=99","#,
            r#""body":"LatentMesh Air state delta\n","author":"{author_hex}","#,
            r#""handle":"gateway-1","created_at":{created_json},"kind":"Post"}},"#,
            r#""signature":"{sig_hex}"}}"#
        ),
        id_json = json_of(&message.id),
        author_hex = identity.id().to_hex(),
        created_json = json_of(&created_at),
        sig_hex = message.signature.to_hex(),
    );
    assert_eq!(actual, expected);
}

#[test]
fn peer_hello_golden_shape() {
    let node = Identity::from_seed(&[3u8; 32]).id();
    let payload = FederationPayload::PeerHello {
        node,
        protocol: latentmesh_agentbbs_bridge::PROTOCOL_VERSION.to_string(),
    };
    let actual = json_of(&payload);
    let expected = format!(
        r#"{{"type":"peer_hello","node":"{node_hex}","protocol":"agentbbs/0.1"}}"#,
        node_hex = node.to_hex(),
    );
    assert_eq!(actual, expected);
}

#[test]
fn ack_golden_shape() {
    let payload = FederationPayload::Ack {
        id: "blake3-hex-message-id".into(),
    };
    let actual = json_of(&payload);
    assert_eq!(actual, r#"{"type":"ack","id":"blake3-hex-message-id"}"#);
}

#[test]
fn agent_id_hex_roundtrips_through_json() {
    let id = Identity::generate().id();
    let json = json_of(&id);
    let parsed: AgentId = serde_json::from_str(&json).unwrap();
    assert_eq!(parsed, id);
}

//! Ignored-by-default integration test against the *real* `agentbbs mcp`
//! stdio binary.
//!
//! Not run by `cargo test -p latentmesh-agentbbs-bridge` (no live binary is
//! assumed to be present in CI or in a fresh checkout) — this is the "add
//! one ignored-by-default integration test... if the build is quick" case
//! ADR-020's task described. It genuinely was quick: a shallow clone of
//! `github.com/ruvnet/agentbbs` (commit read at ADR-020 authoring time)
//! built `cargo build -p agentbbs --bin agentbbs` in well under a minute
//! (workspace warm-cache aside), and the resulting binary's `mcp`
//! subcommand was hand-verified against this crate's [`McpStdioClient`]
//! expectations before this test was written:
//!
//! ```text
//! $ printf '{"jsonrpc":"2.0","id":1,"method":"initialize","params":{}}\n' \
//!     | ./agentbbs mcp
//! {"jsonrpc":"2.0","id":1,"result":{"capabilities":{...},
//!   "protocolVersion":"2024-11-05","serverInfo":{"name":"agentbbs-mcp",...}}}
//! ```
//!
//! ## How to run this test
//!
//! 1. Clone and build the binary (outside this workspace — agentbbs is not
//!    a dependency of it, per ADR-020):
//!    ```sh
//!    git clone --depth=1 https://github.com/ruvnet/agentbbs /tmp/agentbbs
//!    cd /tmp/agentbbs && cargo build -p agentbbs --bin agentbbs
//!    ```
//! 2. Point this test at the built binary and run it explicitly:
//!    ```sh
//!    AGENTBBS_MCP_BIN=/tmp/agentbbs/target/debug/agentbbs \
//!      cargo test -p latentmesh-agentbbs-bridge --test live_agentbbs_mcp -- --ignored
//!    ```
//!
//! If `AGENTBBS_MCP_BIN` is unset, the test skips itself with a clear
//! message rather than failing the run — this keeps `cargo test
//! --workspace` hermetic while still giving anyone with the binary on hand
//! a one-command way to exercise the real roundtrip.

use std::io::Read;
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};

use latentmesh_agentbbs_bridge::mcp::{extract_tool_text, McpStdioClient};

/// A `Read` adapter over a child's stdout, so `McpStdioClient` (generic over
/// any `Read + Write` pair) can drive the subprocess directly.
struct ChildIo {
    child: Child,
    stdout: ChildStdout,
}

impl Read for ChildIo {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        self.stdout.read(buf)
    }
}

impl Drop for ChildIo {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

#[test]
#[ignore = "spawns the real agentbbs mcp subprocess; set AGENTBBS_MCP_BIN and pass --ignored"]
fn live_agentbbs_mcp_roundtrip() {
    let Ok(bin) = std::env::var("AGENTBBS_MCP_BIN") else {
        eprintln!(
            "skipping: set AGENTBBS_MCP_BIN to a built `agentbbs` binary path \
             (see this file's module doc for build instructions)"
        );
        return;
    };

    let mut child = Command::new(&bin)
        .arg("mcp")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()
        .unwrap_or_else(|e| panic!("failed to spawn {bin} mcp: {e}"));

    let stdin: ChildStdin = child.stdin.take().expect("piped stdin");
    let stdout: ChildStdout = child.stdout.take().expect("piped stdout");
    let io = ChildIo { child, stdout };
    let mut client = McpStdioClient::new(io, stdin);

    let init = client.initialize().unwrap();
    assert_eq!(init["protocolVersion"], "2024-11-05");
    assert_eq!(init["serverInfo"]["name"], "agentbbs-mcp");

    let tools = client.list_tools().unwrap();
    let names: Vec<&str> = tools["tools"]
        .as_array()
        .unwrap()
        .iter()
        .map(|t| t["name"].as_str().unwrap())
        .collect();
    for expected in ["list_boards", "read_board", "post_message", "search_memory"] {
        assert!(names.contains(&expected), "missing tool: {expected}");
    }

    let boards = client.list_boards().unwrap();
    let text = extract_tool_text(&boards).expect("tool result has content[0].text");
    // No assertion on board contents (a fresh in-memory Bbs may start
    // empty); the roundtrip itself — spawn, initialize, call a tool, get a
    // well-shaped MCP result — is what this test proves.
    let _ = text;
}

//! Ignored-by-default integration test against a *real* `meshtasticd`
//! device-API TCP server (ADR-019). Not run by `cargo test -p
//! latentmesh-meshtastic` (no live node is assumed present in CI or in a
//! fresh checkout) — same "add one ignored-by-default integration test
//! against the real thing, skip gracefully if the env var is unset"
//! pattern as `latentmesh-agentbbs-bridge/tests/live_agentbbs_mcp.rs`'s
//! `AGENTBBS_MCP_BIN`.
//!
//! This wraps the exact same handshake/round-trip flow as
//! `examples/meshtasticd_interop.rs` (both `#[path]`-include
//! `examples/meshtasticd_interop/core.rs` — see that file's module doc for
//! why it isn't just a shared library module) and asserts on the resulting
//! [`interop_core::InteropReport`] instead of printing it as JSON.
//!
//! ## How to run this
//!
//! ```sh
//! docker run -d --name meshtasticd-interop -p 4403:4403 \
//!   -v /path/to/config.yaml:/etc/meshtasticd/config.yaml:ro \
//!   meshtastic/meshtasticd:latest
//! MESHTASTICD_ADDR=127.0.0.1:4403 \
//!   cargo test -p latentmesh-meshtastic --test live_meshtasticd -- --ignored
//! ```
//!
//! If `MESHTASTICD_ADDR` is unset, the test skips itself with a clear
//! message rather than failing the run.

#[path = "../examples/meshtasticd_interop/core.rs"]
mod interop_core;

#[test]
#[ignore = "connects to a real meshtasticd TCP device API; set MESHTASTICD_ADDR and pass --ignored"]
fn live_meshtasticd_handshake_and_broadcast_round_trip() {
    let Ok(addr) = std::env::var("MESHTASTICD_ADDR") else {
        eprintln!(
            "skipping: set MESHTASTICD_ADDR (e.g. 127.0.0.1:4403) to a live meshtasticd \
             instance's device-API TCP port (see this file's module doc for the docker \
             one-liner)"
        );
        return;
    };

    let report = interop_core::run_interop(&addr);

    // --- Handshake: decoding real firmware-produced protobufs with our
    // hand-rolled codec is itself part of what this test validates.
    assert_ne!(
        report.handshake.my_node_num, 0,
        "expected a real MyNodeInfo.my_node_num from the handshake"
    );
    assert_eq!(
        report.handshake.config_complete_id,
        interop_core::WANT_CONFIG_ID,
        "config_complete_id must echo the id this test's want_config_id sent"
    );

    // --- Broadcast round-trips: these are the checks ADR-019's design
    // assumptions predicted would work, and they do, against real firmware.
    assert!(
        report.broadcast_single_fragment.byte_identical,
        "single-fragment broadcast round-trip did not reproduce the original bytes: {:?}",
        report.broadcast_single_fragment.reassembled_bytes
    );
    assert_eq!(report.broadcast_single_fragment.packet_count, 1);

    // --- Multi-fragment at the production MESHTASTIC_FRAME_MTU (227
    // bytes, revised down from ADR-019's original 233-byte assumption
    // after this exact live interop testing found 232+ bytes rejected with
    // Routing.Error.TOO_LARGE — see MESHTASTIC_FRAME_MTU's doc comment).
    // This is now required to round-trip byte-identical.
    assert!(
        report.broadcast_multi_fragment.byte_identical,
        "multi-fragment broadcast round-trip did not reproduce the original bytes"
    );
    assert_eq!(
        report.broadcast_multi_fragment.packet_count, 2,
        "300 bytes at the 211-usable-byte MTU must fragment into exactly 2 packets"
    );

    // --- MTU-ceiling regression tripwire: a raw 232-byte broadcast that
    // was confirmed rejected during the MESHTASTIC_FRAME_MTU boundary
    // search. Expected to stay rejected (`routed_back == false`); if this
    // ever flips, MESHTASTIC_FRAME_MTU may have room to move back up
    // towards 233 and the discrepancy text records that explicitly rather
    // than this test silently accepting the change.
    if report.mtu_ceiling_tripwire.routed_back {
        eprintln!(
            "NOTE: the {}-byte MTU-ceiling tripwire routed back this run — the previously \
             observed TOO_LARGE rejection may no longer hold; see report.discrepancies",
            report.mtu_ceiling_tripwire.payload_bytes
        );
        assert!(
            report
                .discrepancies
                .iter()
                .any(|d| d.contains("REGRESSION")),
            "tripwire routed back but no REGRESSION discrepancy was recorded"
        );
    }

    // --- Self-addressed unicast: ADR-019's task brief assumed this would
    // also route back through the API. Empirically (see this crate's
    // `data::SIMULATOR_APP_PORTNUM` doc comment and the discrepancy text
    // `run_interop` records) it does not, against this firmware/transport.
    // This is asserted as a known, recorded discrepancy rather than a
    // silent pass/fail — if a future meshtasticd version starts routing it
    // back, that's worth noticing too.
    if report.self_addressed_unicast.routed_back {
        eprintln!(
            "NOTE: self-addressed unicast routed back this run — the previously observed \
             discrepancy may no longer hold for this meshtasticd build; see report.discrepancies"
        );
    } else {
        assert!(
            !report.discrepancies.is_empty(),
            "self-addressed unicast did not route back, but no discrepancy was recorded"
        );
    }
}
